var a=[{title:`Zacznij od łatwej próby`,text:`Wykonaj ruch bez ciężaru lub z najlżejszym przyborem, jaki masz. Dodaj niewielkie obciążenie na serię rozgrzewkową i sprawdź, czy zakres ruchu, oddech i tempo pozostają stabilne. Każdy ruch ma swój ciężar roboczy: obciążenie, które jest wygodne przy wiosłowaniu, może być zdecydowanie zbyt ciężkie do unoszenia bokiem.`},{title:`Powtórzenia w zapasie`,text:`Powtórzenia w zapasie (RIR) to liczba dobrych technicznie powtórzeń, które Twoim zdaniem mógłbyś jeszcze wykonać. W ogólnym treningu praktycznym punktem wyjścia jest kończenie wielu serii z około dwoma lub trzema powtórzeniami w zapasie, choć nie musisz tego osiągać za każdym razem. Jeśli planowana seria 10 powtórzeń wydaje się taka, że mógłbyś zrobić 10 kolejnych, obciążenie może być zbyt lekkie dla Twojego celu.`},{title:`Dostosuj w trakcie treningu`,text:`Załóżmy, że plan zakłada trzy serie po osiem do dwunastu. Jeśli pierwsza seria kończy się na ośmiu z chwiejną techniką i bez zapasu, zmniejsz obciążenie. Jeśli dwanaście powtórzeń jest płynnych i nadal dość łatwych, spróbuj niewielkiego zwiększenia w następnej serii. Odpocznij na tyle długo, by ocenić, czy problem wynikał z ciężaru, czy ze zmęczenia.`},{title:`Gdy skoki ciężaru są zbyt duże`,text:`Jeśli kolejny hantel jest zbyt ciężki, dodaj powtórzenie, kontrolowaną pauzę lub kolejną dobrą serię. Jeśli nawet najlżejszy ciężar jest zbyt duży, użyj masy ciała, gumy oporowej lub innej dźwigni. Nigdy nie wyciskaj nieudanych powtórzeń na siłę, by osiągnąć zadaną liczbę.`},{title:`Korzystanie z TrainUp`,text:`Twój plan podaje serie, powtórzenia i przerwy, ale nie ciężary, więc obciążenie wybierasz sam. Podczas treningu zapisuj powtórzenia, które faktycznie wykonałeś, a po nim oceń wysiłek sesji od 1 do 10. Jeśli czujesz ból, masz zawroty głowy lub ciągle tracisz technikę, przerwij lub zmień ćwiczenie; nie dodawaj oporu. „Czuję ból” kończy bieżące ćwiczenie natychmiast.`}];var o=[{label:`Stanowisko ACSM z 2026 roku`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`ACSM: podsumowanie wytycznych dotyczących treningu oporowego z 2026 roku`,url:`https://acsm.org/resistance-training-guidelines-update-2026/`},{label:`Mayo Clinic: bezpieczeństwo i technika treningu z obciążeniem`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`}];var n={sections:a,sources:o};export{n as default,a as sections,o as sources};